def is_prime(n):
    if n < 2:
        return False
    return all(n % d != 0 for d in range(2, int(n ** 0.5) + 1))
print(sum(n for n in range(11, 30) if is_prime(n)))

import math
N = 1
for i in range(1, 11):
    N *= i
cnt = 0
for d in range(1, math.isqrt(N) + 1):
    if N % d == 0:
        cnt += 1 if d * d == N else 2
print(cnt)

def ndiv(n):
    return sum(1 for k in range(1, n + 1) if n % k == 0)
print(sum(1 for n in range(1, 501) if ndiv(n) == 3))

count = 0
for b in range(2, 101):
    v = 0
    for digit in (1, 1, 0):
        v = v * b + digit
    if v % 7 == 0:
        count += 1
print(count)

N = 360
divs = [d for d in range(1, N + 1) if N % d == 0]
def gcd_brute(x, y):
    return max(d for d in range(1, min(x, y) + 1) if x % d == 0 and y % d == 0)
def lcm_brute(x, y):
    return min(m for m in range(1, N + 1) if m % x == 0 and m % y == 0)
count = 0
for a in divs:
    for b in divs:
        if gcd_brute(a, b) == 12 and lcm_brute(a, b) == N:
            count += 1
print(count)

